// This file is generated by AI.

// 实时预览面板: 内嵌 iframe 加载 WebGAL 引擎, 通过 /api/webgalsync 网关联动光标。
//
// iframe 保持 16:9 横向画布: 引擎在竖屏窗口下会把画面旋转 90°, 因此必须保证宽大于高。
//
// 预览是**跨源** iframe (编辑器在 tauri://, 引擎在 http://127.0.0.1:8899): 浏览器按源
// 授权的能力 (全屏) 不会自动给到它, 必须在这里逐条显式授予, 见下面那个 effect 与 iframe
// 的 `allow` 属性。

import { ArrowClockwiseRegular, OpenRegular, Speaker2Regular, SpeakerMuteRegular } from '@fluentui/react-icons';
import { Button, Switch } from '@fluentui/react-components';
import { getCurrentWindow } from '@tauri-apps/api/window';
import { openUrl } from '@tauri-apps/plugin-opener';
import { useEffect, useRef, useState } from 'react';

import { resolveProjectEngine } from '../lib/engine';
import { previewClient } from '../preview/client';
import { createPreviewOutputSettingsMessage } from '../preview/audio-bridge';
import {
  applyPreviewFullscreenAction,
  previewFullscreenTransition,
  type PreviewFullscreenStatus,
} from '../preview/fullscreen';
import { createId } from '../preview/protocol';
import { useAppStore } from '../state/store';

const BOOTSTRAP_REQUEST = 'webgal.preview.bootstrap.request';
const BOOTSTRAP_PROVIDE = 'webgal.preview.bootstrap.provide';

export function PreviewPanel() {
  const projectPath = useAppStore((s) => s.projectPath);
  // 项目用哪个引擎由"项目绑定 -> 引擎列表第一个"决定 (见 lib/engine.ts)
  const enginePath = useAppStore((s) => resolveProjectEngine(s.settings, s.projectBindings, s.projectPath)?.path);
  const settings = useAppStore((s) => s.settings);
  const updateSettings = useAppStore((s) => s.updateSettings);
  const previewReady = useAppStore((s) => s.previewReady);
  const previewReloadToken = useAppStore((s) => s.previewReloadToken);

  const iframeRef = useRef<HTMLIFrameElement>(null);
  const launchIdRef = useRef(createId());
  const [frame, setFrame] = useState<{ url: string; key: string } | null>(null);
  const [error, setError] = useState<string | null>(null);

  const muted = settings.previewMuted;

  /*
   * 静音: 给预览页面发一条 `webgal.preview.output-settings` 消息。
   *
   * 页面里那段注入脚本 (见 `src-tauri/src/service/preview/audio_bridge.rs`) 会把它记成全局
   * 输出系数, 立刻压住**所有**已存在的 audio/video, 之后新建的也一样 —— 因此不依赖引擎,
   * 也不需要引擎配合。页面加载时的初始值已经写在注入脚本里, 这里负责之后的切换与重挂补发。
   *
   * 这里**现取**开关值而不是捕获闭包: 于是这个函数不必进任何依赖数组, 也就能安全地挂在
   * iframe 的 `onLoad` 上 —— 关键是别把 `muted` 放进"注册站点"那个 effect 的依赖里, 否则
   * 拨一下静音就会重新注册站点并换 key 重挂 iframe, 整个预览白重载一次。
   */
  const postMuted = () => {
    const target = iframeRef.current?.contentWindow;
    if (!target) return;
    const current = useAppStore.getState().settings.previewMuted;
    target.postMessage(createPreviewOutputSettingsMessage(current), '*');
  };

  /*
   * 让宿主服务器也记住当前开关: 下次页面加载时注入的初始状态就是静音的, 不会先响一声。
   *
   * `setMuted` 不依赖预览是否已启动 (它只写服务器上的状态), 因此这个 effect 在挂载时就会
   * 跑一次 —— 早于下面那段注册站点的异步流程, 注入脚本拿到的初始值就是准的。
   */
  useEffect(() => {
    void previewClient.setMuted(muted);
  }, [muted]);

  // 预览重挂/首次连上都补发一次 (iframe 的 onLoad 也走这里)
  useEffect(() => {
    if (previewReady) postMuted();
  }, [previewReady, muted, frame]);

  useEffect(() => {
    if (!projectPath) {
      setFrame(null);
      return;
    }
    let cancelled = false;
    setError(null);
    (async () => {
      try {
        previewClient.resetSite();
        const url = await previewClient.ensureSite(projectPath, enginePath);
        if (cancelled) return;
        if (url) {
          const id = createId();
          launchIdRef.current = id;
          await previewClient.bindEmbeddedLaunchId(id);
          if (!cancelled) setFrame({ url, key: id });
        } else {
          setError('预览服务器启动失败');
        }
      } catch (e) {
        if (!cancelled) setError(String(e));
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [projectPath, enginePath]);

  // bootstrap 握手: 引擎在 iframe 内请求 embeddedLaunchId
  useEffect(() => {
    const handler = (event: MessageEvent) => {
      const iframeWindow = iframeRef.current?.contentWindow;
      if (!iframeWindow || event.source !== iframeWindow) return;
      const data = event.data as { type?: string } | null;
      if (data && typeof data === 'object' && data.type === BOOTSTRAP_REQUEST) {
        iframeWindow.postMessage({ type: BOOTSTRAP_PROVIDE, embeddedLaunchId: launchIdRef.current }, '*');
      }
    };
    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, [frame]);

  /*
   * 全屏: 引擎底栏画不画"全屏"按钮, 取决于它页面里的 `document.fullscreenEnabled`
   * (见引擎的 `hooks/useFullScreen`)。fullscreen 的默认允许名单是 `self`, 跨源 iframe
   * 拿不到这个能力, `fullscreenEnabled` 就是 false, 按钮干脆不画 —— 这正是"Terre 的预览有、
   * Ink 的没有"的原因: Terre 的预览 iframe 与编辑器同源, 白捡了 `self`。授权本身写在 iframe
   * 的 `allow` 属性上, 这里负责授权之后的窗口侧处理。
   *
   * Windows 上 Tauri 自己会把"webview 里有全屏元素"映射成窗口全屏 (tauri-runtime-wry 的
   * `add_ContainsFullScreenElementChanged`), 所以下面的动作大多是幂等的重复调用; 真正要补的是
   * "最大化窗口 + 无边框全屏"那个组合 —— tao 不清最大化状态, 底部会留下一条任务栏高的黑边。
   * 折算与执行都在 `preview/fullscreen` 里 (纯函数 + 可注入的窗口接口, 有单测钉住顺序)。
   */
  useEffect(() => {
    const win = getCurrentWindow();
    let status: PreviewFullscreenStatus = { mirrored: false, corrected: false };

    /*
     * 进入全屏前窗口是不是最大化。
     *
     * 只在**不在全屏**时记录: 全屏那一次的 resize 正是我们要修的形态变化, 不能拿它当用户想要的
     * 窗口样子。它也可能早于我们的 `fullscreenchange` 到达, 但那时窗口还停在最大化状态, 记下来
     * 的仍是"进入前最大化", 两种先后都对。
     */
    let windowWasMaximized = false;
    const syncWindowWasMaximized = () => {
      if (document.fullscreenElement !== null) return;
      void win
        .isMaximized()
        .then((value) => {
          windowWasMaximized = value;
        })
        .catch(() => {
          // 问不到窗口形态 (例如前端跑在浏览器里) 就当作不是最大化, 不影响预览本身
        });
    };

    const onFullscreenChange = () => {
      // 只管"预览 iframe 自己"成了全屏元素的情况 (顶层文档里别的元素全屏与我们无关)
      const fullscreenElement = document.fullscreenElement;
      const active = fullscreenElement !== null && fullscreenElement === iframeRef.current;
      const next = previewFullscreenTransition(status, { fullscreenActive: active, windowWasMaximized });
      status = { mirrored: next.mirrored, corrected: next.corrected };
      void applyPreviewFullscreenAction(win, next.action).catch((error) => {
        // 窗口侧失败不该影响预览本身: 元素全屏照常生效, 只是窗口形态可能不对
        console.error('预览全屏补正失败', error);
      });
    };

    // 先取一次, 之后靠 resize 跟上 (打开/关闭项目都会改窗口形态, 见 lib/window.ts)
    syncWindowWasMaximized();
    const unlistenResize = win.onResized(syncWindowWasMaximized);
    document.addEventListener('fullscreenchange', onFullscreenChange);
    return () => {
      document.removeEventListener('fullscreenchange', onFullscreenChange);
      void unlistenResize.then((off) => off());
      // 面板卸载会把 iframe 一起摘掉, 元素全屏随之结束, 而那次 fullscreenchange 我们未必还能听到
      if (status.corrected) void applyPreviewFullscreenAction(win, { kind: 'restore-maximized' }).catch(() => {});
    };
  }, []);

  const reload = async () => {
    if (!frame) return;
    const id = createId();
    launchIdRef.current = id;
    await previewClient.bindEmbeddedLaunchId(id);
    setFrame({ url: frame.url, key: id });
  };

  // 模板切换等场景通过 store 令牌触发整体重挂 (兼容旧版引擎)
  useEffect(() => {
    if (previewReloadToken > 0) void reload();
  }, [previewReloadToken]);

  return (
    <div className="preview-panel">
      <div className="preview-toolbar">
        <span className={`preview-ready${previewReady ? ' ready' : ''}`}>{previewReady ? '● 已连接' : '○ 未连接'}</span>
        <span className="preview-toolbar-spacer" />
        <Switch
          checked={settings.autoSyncPreview}
          onChange={(_, data) => updateSettings({ autoSyncPreview: data.checked })}
          label="预览"
        />
        <Button
          icon={muted ? <SpeakerMuteRegular /> : <Speaker2Regular />}
          appearance="subtle"
          title={muted ? '取消静音' : '静音预览'}
          onClick={() => updateSettings({ previewMuted: !muted })}
        />
        <Button icon={<ArrowClockwiseRegular />} appearance="subtle" title="刷新预览" onClick={() => void reload()} />
        <Button
          icon={<OpenRegular />}
          appearance="subtle"
          title="在浏览器中打开预览"
          disabled={!frame}
          onClick={() => frame && void openUrl(frame.url)}
        />
      </div>
      <div className="preview-frame-wrap">
        {error ? (
          <div className="preview-error">{error}</div>
        ) : frame ? (
          <div className="preview-frame-box">
            <iframe
              key={frame.key}
              ref={iframeRef}
              src={frame.url}
              className="preview-frame"
              title="WebGAL 预览"
              // 跨源 iframe 得显式授权, 引擎才会画"全屏"按钮 (理由见上面那段注释); 两种写法
              // 都给: `allow` 是新写法且优先级更高, `allowFullScreen` 兜住只认老属性的实现
              allow="autoplay; fullscreen"
              allowFullScreen
              onLoad={postMuted}
            />
          </div>
        ) : (
          <div className="preview-loading">正在启动预览…</div>
        )}
      </div>
    </div>
  );
}
